/*
 * Spawns Bio3 wobbling mesh task for a single target.
 */
// FUNCTION: FF7 0x005a2fda
void __cdecl BattleFx_MagicSpawnBio3PerTarget(int actor)
{
    BattleFxBio3Task *task;

    task = (BattleFxBio3Task *)BATTLE_NEW_TASK_SLOT(BattleFx_MagicBio3TimelineTask);
    task->targetIndex = actor;
    Battle_GetBoneWorldPos(actor, g_BattleActorRecords[actor].targetBone, &task->posX);
    task->effectSize = Battle_GetActorScaledEffectSize(actor);
}

/*
 * Timeline task managing model scaling and sprite emission for Bio3.
 */
// FUNCTION: FF7 0x005a303f
void __cdecl BattleFx_MagicBio3TimelineTask(void)
{
    int stackWords; /* Unreferenced stack padding preserved for VC5 /Od frame size (see lib/codegen.h). */
    BattleFxBio3Slot *task;
    BattleFxBio3TimelineRecord *child;

    task = (BattleFxBio3Slot *)BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleIsPaused != 0) {
        return;
    }
    if (task->step == 0) {
        child = (BattleFxBio3TimelineRecord *)BATTLE_NEW_TASK_SLOT(BattleFx_MagicBio3PulsingScaledModelTask);
        child->pos = task->base;
        child->scale = task->scale;
    }
    if (task->step >= 0 && task->step < 8 && task->step % 2 == 0) {
        child = (BattleFxBio3TimelineRecord *)BATTLE_NEW_TASK_SLOT(BattleFx_MagicBio3WobblingMeshTask);
        child->timer = task->step / 2;
        child->posX = task->baseX + (rand() % 2048) + -1024;
        child->posY = task->baseY + (rand() % 2048) + -1024;
        child->posZ = task->baseZ + (rand() % 2048) + -1024;
        child->scale = task->scale;
    }
    if (task->step == 0) {
        child = (BattleFxBio3TimelineRecord *)BATTLE_NEW_TASK_SLOT(BattleFx_MagicBio3RisingFadeSpriteEmitterTask);
        child->pos = task->base;
        child->scale = task->scale;
    }
    if (task->step == 30) {
        Battle_PostActorHitOrHurtMessage(task->recordType);
    }
    if (task->step == 30) {
        task->ownerSlot = BATTLE_TASK_FREE;
    }
    (task->step)++;
}

