/*
 * Renders and animates the pulsing scaled model effect for Bio3.
 */
// FUNCTION: FF7 0x005a3d8a
void __cdecl BattleFx_MagicBio3PulsingScaledModelTask(void)
{
    BattleFxFixedScaleVec *scaleVecPtr;
    int stage;
    int sinScale;
    int envelope;
    int stackWords[2]; /* Unreferenced stack padding preserved for VC5 /Od frame size (see lib/codegen.h). */
    BattleFxBio3PulsingModel *task;
    int padLocal; /* Unreferenced stack padding preserved for VC5 /Od frame size (see lib/codegen.h). */
    PsxMatrix *matrix;
    int clamped8;

    task = (BattleFxBio3PulsingModel *)BATTLE_CURRENT_TASK_SLOT;
    (*(int *)&g_BattleMagicBio3_ModelData2) = Gfx_ModelTableGetRenderObject(0, g_BattleMagicBio3_LoadedModelTable);
    matrix = (PsxMatrix *)Gfx_GetPsxScratchpadPtr(0);
    scaleVecPtr = (BattleFxFixedScaleVec *)((int)matrix + 0x1E);
    sinScale = (SinFixed(task->phase * 0x111) << 8 >> 13) + 0xE80;
    stage = task->phase;
    if (stage < 10) {
        envelope = (stage << 12) / 10;
    } else {
        stage -= 10;
        if (stage < 20) {
            envelope = 0x1000;
        } else {
            stage -= 20;
            if (stage < 10) {
                envelope = stage * -0x1000 / 10 + 0x1000;
            } else {
                task->ownerSlot = BATTLE_TASK_FREE;
                return;
            }
        }
    }
    sinScale = (sinScale * envelope >> 12) * task->scale >> 12;
    if (sinScale < 0x7FFF) {
        clamped8 = sinScale;
    } else {
        clamped8 = 0x7FFF;
    }
    scaleVecPtr->scaleZ = clamped8;
    scaleVecPtr->scaleY = clamped8;
    scaleVecPtr->scaleX = clamped8;
    if (g_BattleIsPaused == 0) {
        g_BattleMagicBio3_PolySetIndex = task->phase & 0xF;
        Gfx_ForEachPolygonSetPart((DxGroupPartCallback)BattleFx_MagicBio3ReadPolygonSetVertexFloat, *(int *)((char *)(*(int *)&g_BattleMagicBio3_ModelData2) + 4));
    }
    g_BattleMagicBio3_SpriteDrawReq1.transX = task->posX;
    g_BattleMagicBio3_SpriteDrawReq1.transY = task->posY;
    g_BattleMagicBio3_SpriteDrawReq1.transZ = task->posZ;
    MultiplyMatrix(&g_BattleCameraTransform, &g_BattleMagicBio3_SpriteDrawReq1, matrix);
    ScaleMatrix(matrix, scaleVecPtr);
    SetRotMatrix(matrix);
    SetTransMatrix(matrix);
    g_BattleMagicBio3_DrawListHandle = BattleFx_SubmitModelDraw((BattleFxModelDraw *)&g_BattleMagicBio3_ModelData2, g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED, 0xC, g_BattleMagicBio3_DrawListHandle);
    if (g_BattleIsPaused == 0) {
        (task->phase)++;
    }
}

/*
 * Emits rising fading sprite particles around target entities for Bio3.
 */
// FUNCTION: FF7 0x005a3f8c
void __cdecl BattleFx_MagicBio3RisingFadeSpriteEmitterTask(void)
{
    int sizeVal;
    BattleFxBio3RisingSpriteEmitter *taskPtr;
    BattleMagicBio3RisingSpriteRecord *sprite;
    int clamped;

    taskPtr = (BattleFxBio3RisingSpriteEmitter *)BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleIsPaused != 0) {
        return;
    }
    if (taskPtr->frameCount % 1 == 0) {
        sprite = (BattleMagicBio3RisingSpriteRecord *)BATTLE_NEW_TASK_SLOT(BattleFx_MagicBio3RisingFadeSpriteTask);
        sprite->posX = taskPtr->posX + ((rand() % 2000 - 1000) * taskPtr->spread >> 12);
        sprite->heightY = 0;
        sprite->posY = taskPtr->posY + ((rand() % 2000 - 1000) * taskPtr->spread >> 12);
        sizeVal = (rand() % 2560 + 4096) * taskPtr->spread >> 12;
        if (sizeVal < 32768) {
            clamped = sizeVal;
        } else {
            clamped = 0x7FFF;
        }
        sprite->size = clamped;
        sprite->riseSpeed = rand() % 140 + 10;
    }
    (taskPtr->frameCount)++;
    if (taskPtr->frameCount >= 30) {
        taskPtr->ownerSlot = BATTLE_TASK_FREE;
    }
}

/*
 * Renders and steps a rising fading sprite particle for Bio3.
 */
// FUNCTION: FF7 0x005a40dd
void __cdecl BattleFx_MagicBio3RisingFadeSpriteTask(void)
{
    int localFrame;
    BattleFxBioRisingFadeSprite *task;

    task = (BattleFxBioRisingFadeSprite *)BATTLE_CURRENT_TASK_SLOT;
    g_BattleMagicBio3_SpriteDrawReq2.table = Gfx_ModelTableGetLoadedRecord(1, g_BattleMagicBio3_LoadedModelTable);
    g_BattleMagicBio3_SpriteDrawReq2.tableAlt = Gfx_ModelTableGetSpriteObject(1, g_BattleMagicBio3_LoadedModelTable);
    localFrame = task->frame;
    if (localFrame < 10) {
        g_BattleMagicBio3_SpriteDrawReq3.colorWord = 0x2C808080;
    } else {
        localFrame -= 10;
        if (localFrame < 10) {
            g_BattleMagicBio3_SpriteDrawReq3.code = 0x2E;
            g_BattleMagicBio3_SpriteDrawReq3.colorB = localFrame * -0x80 / 10 + 0x80;
            g_BattleMagicBio3_SpriteDrawReq3.colorG = g_BattleMagicBio3_SpriteDrawReq3.colorB;
            g_BattleMagicBio3_SpriteDrawReq3.colorR = g_BattleMagicBio3_SpriteDrawReq3.colorG;
        } else {
            task->ownerSlot = BATTLE_TASK_FREE;
            return;
        }
    }
    g_BattleMagicBio3_SpriteDrawReq3.frame = task->frame % 7;
    BattleFx_InstallBillboardMatrix(&task->posX, (short)task->size, 0);
    g_BattleMagicBio3_DrawListHandle = BattleFx_SubmitSpriteDraw(&g_BattleMagicBio3_SpriteDrawReq2.table, g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED, 0xC, g_BattleMagicBio3_DrawListHandle);
    if (g_BattleIsPaused == 0) {
        (task->frame)++;
        task->posY -= task->riseSpeed;
    }
}
